package legacymigration

var preflightChecks = []checkSpec{
	{"organization-owned products require an explicit ownership policy", `SELECT id FROM {{source}}.products WHERE owner_type<>'user'`},
	{"organization-owned or non-NGN wallets are unsupported", `SELECT id FROM {{source}}.wallets WHERE owner_type<>'user' OR currency<>'NGN'`},
	{"every account must have exactly one user wallet", `SELECT u.id FROM {{source}}.users u LEFT JOIN {{source}}.wallets w ON w.owner_type='user' AND w.owner_id=u.id GROUP BY u.id HAVING count(w.id)<>1`},
	{"wallet owner does not exist", `SELECT w.id FROM {{source}}.wallets w LEFT JOIN {{source}}.users u ON u.id=w.owner_id WHERE u.id IS NULL`},
	{"product owner does not exist", `SELECT p.id FROM {{source}}.products p LEFT JOIN {{source}}.users u ON u.id=p.owner_id WHERE u.id IS NULL`},
	{"multiple payout accounts require an explicit selection", `SELECT user_id FROM {{source}}.user_bank_accounts GROUP BY user_id HAVING count(*)>1`},
	{"payout account number is incompatible", `SELECT id FROM {{source}}.user_bank_accounts WHERE account_number !~ '^[0-9]{10}$'`},
	{"account IDs exceed wallet-number capacity", `SELECT id FROM {{source}}.users WHERE id<1 OR id>999999999`},
	{"duplicate destination wallet numbers", `SELECT {{wallet_number}} FROM {{source}}.users u JOIN {{source}}.wallets w ON w.owner_type='user' AND w.owner_id=u.id GROUP BY 1 HAVING count(*)>1`},
	{"wallet balances exceed exact NUMERIC(12,2) capacity", `SELECT id FROM {{source}}.wallets WHERE balance<0 OR balance>9999999999.99 OR balance<>round(balance,2)`},
	{"legacy generic ledger types require a reviewed financial mapping", `SELECT id FROM {{source}}.wallet_transactions WHERE type NOT IN ('deposit','deposit_reversal','withdrawal_reserved','withdrawal_refund','order_payment','sale_credit','transfer_out','transfer_in','transfer_refund')`},
	{"ledger amounts exceed exact NUMERIC(12,2) capacity", `SELECT id FROM {{source}}.wallet_transactions WHERE amount<=0 OR amount>9999999999.99 OR amount<>round(amount,2)`},
	{"deposit amounts exceed exact NUMERIC(12,2) capacity", `SELECT id FROM {{source}}.wallet_deposits WHERE amount<=0 OR amount>9999999999.99 OR amount<>round(amount,2) OR verified_amount>9999999999.99 OR verified_amount<>round(verified_amount,2)`},
	{"revenue amounts or rates cannot be preserved exactly", `SELECT id FROM {{source}}.platform_revenue WHERE gross_amount<=0 OR gross_amount>9999999999.99 OR gross_amount<>round(gross_amount,2) OR amount<=0 OR amount>9999999999.99 OR amount<>round(amount,2) OR rate_percent<0 OR rate_percent>999.99 OR rate_percent<>round(rate_percent,2)`},
	{"negotiation prices or quantities cannot be preserved exactly", `SELECT id FROM {{source}}.negotiations WHERE initial_offer_price<0 OR initial_offer_price>9999999999.99 OR initial_offer_price<>round(initial_offer_price,2) OR current_offer_price<0 OR current_offer_price>9999999999.99 OR current_offer_price<>round(current_offer_price,2) OR quantity<=0 OR quantity::double precision::numeric<>quantity`},
	{"message offer prices cannot be preserved exactly", `SELECT id FROM {{source}}.negotiation_messages WHERE offer_price<0 OR offer_price>9999999999.99 OR offer_price<>round(offer_price,2)`},
	{"cart amounts or quantities cannot be preserved exactly", `SELECT id FROM {{source}}.cart_items WHERE quantity<=0 OR price_per_unit<=0 OR total_price<=0 OR quantity::double precision::numeric<>quantity OR price_per_unit::double precision::numeric<>price_per_unit OR total_price::double precision::numeric<>total_price`},
	{"withdrawal amounts exceed exact NUMERIC(12,2) capacity", `SELECT id FROM {{source}}.wallet_withdrawals WHERE amount<=0 OR amount>9999999999.99 OR amount<>round(amount,2)`},
	{"transfer amounts exceed exact NUMERIC(12,2) capacity", `SELECT id FROM {{source}}.wallet_transfers WHERE amount<=0 OR amount>9999999999.99 OR amount<>round(amount,2)`},
	{"withdrawal ownership disagrees with its wallet", `SELECT t.id FROM {{source}}.wallet_withdrawals t JOIN {{source}}.wallets w ON w.id=t.wallet_id WHERE w.owner_type<>'user' OR w.owner_id<>t.user_id`},
	{"transfer ownership disagrees with its wallets", `SELECT t.id FROM {{source}}.wallet_transfers t JOIN {{source}}.wallets s ON s.id=t.sender_wallet_id JOIN {{source}}.wallets r ON r.id=t.recipient_wallet_id WHERE s.owner_id<>t.sender_id OR r.owner_id<>t.recipient_id OR s.owner_type<>'user' OR r.owner_type<>'user'`},
	{"deposits have an unsupported state", `SELECT id FROM {{source}}.wallet_deposits WHERE status NOT IN ('pending','processing','successful','failed','expired','reversed')`},
	{"withdrawals have an unsupported state", `SELECT id FROM {{source}}.wallet_withdrawals WHERE status NOT IN ('pending','processing','paid','rejected','failed','cancelled','expired')`},
	{"transfers have an unsupported state", `SELECT id FROM {{source}}.wallet_transfers WHERE status NOT IN ('pending','completed','rejected','cancelled','expired')`},
	{"virtual accounts have an unsupported state or account number", `SELECT id FROM {{source}}.wallet_virtual_accounts WHERE status NOT IN ('pending','active','failed') OR (account_number<>'' AND account_number !~ '^[0-9]{10}$') OR (status='active' AND account_number='') OR identity_kind NOT IN ('','bvn','nin')`},
	{"products cannot round-trip through the current numeric fields", `SELECT id FROM {{source}}.products WHERE quantity<0 OR price<0 OR quantity::double precision::numeric<>quantity OR price::double precision::numeric<>price`},
	{"multi-item or empty orders require a separate order-model migration", `SELECT o.id FROM {{source}}.orders o LEFT JOIN {{source}}.order_items i ON i.order_id=o.id GROUP BY o.id HAVING count(i.id)<>1`},
	{"order totals disagree with their item or currency", `SELECT o.id FROM {{source}}.orders o JOIN {{source}}.order_items i ON i.order_id=o.id WHERE o.total_amount<>i.total_price OR i.quantity*i.unit_price<>i.total_price OR o.currency<>'NGN' OR o.total_amount::double precision::numeric<>o.total_amount OR i.quantity::double precision::numeric<>i.quantity`},
	{"delivery states require an explicit mapping", `SELECT id FROM {{source}}.deliveries WHERE status NOT IN ('pending','confirmed','picked_up','in_transit','delivered','failed','cancelled')`},
	{"cart entries without negotiations are unsupported by the current cart", `SELECT id FROM {{source}}.cart_items WHERE negotiation_id IS NULL`},
	{"cross-state neighbors require an explicit geographic mapping", `SELECT e.lga_id FROM {{source}}.lga_neighbors e JOIN {{source}}.lgas l ON l.id=e.lga_id JOIN {{source}}.lgas n ON n.id=e.neighbor_lga_id WHERE l.state_id<>n.state_id`},
	{"conversations require an attributable creator and supported type", `SELECT id FROM {{source}}.conversations WHERE created_by IS NULL OR conversation_type NOT IN ('private','group')`},
	{"chat media needs a separate attachment migration", `SELECT id FROM {{source}}.chat_messages WHERE NULLIF(btrim(media_url),'') IS NOT NULL`},
	{"unknown event product or account references", `SELECT e.id FROM {{source}}.market_events e LEFT JOIN {{source}}.products p ON p.id=e.product_id LEFT JOIN {{source}}.users u ON u.id=e.user_id WHERE (e.product_id IS NOT NULL AND p.id IS NULL) OR (e.user_id IS NOT NULL AND u.id IS NULL)`},
}

var paymentPreflight = checkSpec{"payment amounts cannot be preserved exactly", `SELECT id FROM {{source}}.payments WHERE amount<=0 OR amount>9999999999.99 OR amount<>round(amount,2)`}
var paymentVerification = checkSpec{"payment ownership, amounts, provider references, and states preserved", `SELECT p.id FROM {{source}}.payments p JOIN {{target}}.legacy_import_mappings m ON m.source_table='orders' AND m.source_id=p.order_id LEFT JOIN {{target}}.payments n ON n.id=p.id WHERE n.id IS NULL OR ROW(n.order_id,n.reference,n.transaction_id,n.amount,n.currency,n.status,n.provider,n.created_at,n.updated_at) IS DISTINCT FROM ROW(m.target_id,p.reference,p.transaction_id,p.amount,p.currency,p.status,p.provider,p.created_at,p.updated_at)`}

var verificationChecks = []checkSpec{
	{"payout details and canonical wallet identifiers preserved", `SELECT u.id FROM {{source}}.users u JOIN {{source}}.wallets w ON w.owner_type='user' AND w.owner_id=u.id JOIN {{target}}.legacy_import_mappings m ON m.source_table='users' AND m.source_id=u.id LEFT JOIN {{source}}.user_bank_accounts b ON b.user_id=u.id JOIN {{target}}.farmers f ON f.id=m.target_id WHERE ROW(f.bank_name,f.bank_code,f.account_name,f.account_number,f.wallet_number) IS DISTINCT FROM ROW(b.bank_name,b.bank_code,b.account_name,b.account_number,{{wallet_number}})`},
	{"original wallet numbers and conversion ownership recorded exactly", `SELECT w.id FROM {{source}}.wallets w JOIN {{source}}.users u ON u.id=w.owner_id JOIN {{target}}.legacy_import_mappings m ON m.source_table='users' AND m.source_id=u.id LEFT JOIN {{target}}.legacy_wallet_numbers n ON n.source_wallet_id=w.id WHERE n.source_wallet_id IS NULL OR ROW(n.source_user_id,n.target_user_id,n.legacy_number,n.wallet_number,n.conversion) IS DISTINCT FROM ROW(u.id,m.target_id,w.wallet_number,{{wallet_number}},CASE WHEN w.wallet_number ~ '^[0-9]{10}$' THEN 'preserved' ELSE 'generated' END)`},
	{"virtual-account ownership, provider references, bank details, consent, and states preserved", `SELECT v.id FROM {{source}}.wallet_virtual_accounts v JOIN {{target}}.legacy_import_mappings m ON m.source_table='users' AND m.source_id=v.user_id LEFT JOIN {{target}}.wallet_virtual_accounts n ON n.id=v.id WHERE n.id IS NULL OR ROW(n.farmer_id,n.provider,n.tx_ref,n.order_ref,n.provider_ref,n.account_number,n.bank_name,n.account_name,n.currency,n.status,n.identity_kind,n.consent_version,n.consent_at,n.failure_reason,n.last_checked_at,n.created_at,n.updated_at) IS DISTINCT FROM ROW(m.target_id,v.provider,v.tx_ref,v.order_ref,v.provider_ref,v.account_number,v.bank_name,v.account_name,v.currency,v.status,v.identity_kind,v.consent_version,v.consent_at,v.failure_reason,v.last_checked_at,v.created_at,v.updated_at)`},
	{"account identity, credentials, account type, and wallet-only admin flags preserved", `SELECT u.id FROM {{source}}.users u JOIN {{target}}.legacy_import_mappings m ON m.source_table='users' AND m.source_id=u.id
 LEFT JOIN {{target}}.farmers f ON f.id=m.target_id WHERE f.id IS NULL OR ROW(f.full_name,f.phone,f.email,f.password_hash,f.role,f.is_admin,f.deleted_at,f.created_at,f.updated_at) IS DISTINCT FROM ROW(u.full_name,u.phone,u.email,u.password_hash,u.role,u.is_admin,u.deleted_at,u.created_at,u.updated_at) OR f.admin_role<>'' OR f.selfie_captured_at IS NOT NULL OR f.phone_verified_at IS NOT NULL`},
	{"listing identity, ownership, stock, price, and sale status preserved", `SELECT p.id FROM {{source}}.products p JOIN {{target}}.legacy_import_mappings m ON m.source_table='products' AND m.source_id=p.id JOIN {{target}}.legacy_import_mappings u ON u.source_table='users' AND u.source_id=p.owner_id
 LEFT JOIN {{target}}.crops c ON c.id=m.target_id WHERE c.id IS NULL OR c.farmer_id<>u.target_id OR c.name<>p.name OR c.quantity::numeric<>p.quantity OR c.price_per_unit::numeric<>p.price OR c.unit<>p.unit OR c.listed_for_sale<>(p.status='active') OR c.moderation_blocked`},
	{"every wallet balance and owner preserved exactly", `SELECT w.id FROM {{source}}.wallets w JOIN {{target}}.legacy_import_mappings m ON m.source_table='wallets' AND m.source_id=w.id JOIN {{target}}.legacy_import_mappings u ON u.source_table='users' AND u.source_id=w.owner_id
 LEFT JOIN {{target}}.wallets n ON n.id=m.target_id WHERE n.id IS NULL OR ROW(n.farmer_id,n.balance,n.currency,n.created_at,n.updated_at) IS DISTINCT FROM ROW(u.target_id,w.balance,w.currency,w.created_at,w.updated_at)`},
	{"ledger references, signs, amounts, timestamps, and wallet ownership preserved", `SELECT t.id FROM {{source}}.wallet_transactions t JOIN {{target}}.legacy_import_mappings m ON m.source_table='wallets' AND m.source_id=t.wallet_id
 LEFT JOIN {{target}}.wallet_transactions n ON n.id=t.id WHERE n.id IS NULL OR ROW(n.wallet_id,n.type,n.amount,n.reference,n.created_at) IS DISTINCT FROM ROW(m.target_id,t.type,t.amount,t.reference,t.created_at)`},
	{"deposit references, verified amounts, states, and wallet ownership preserved", `SELECT d.id FROM {{source}}.wallet_deposits d JOIN {{target}}.legacy_import_mappings m ON m.source_table='wallets' AND m.source_id=d.wallet_id
 LEFT JOIN {{target}}.wallet_deposits n ON n.id=d.id WHERE n.id IS NULL OR ROW(n.wallet_id,n.reference,n.provider,n.provider_transaction_id,n.amount,n.currency,n.verified_amount,n.verified_currency,n.status,n.created_at,n.updated_at) IS DISTINCT FROM ROW(m.target_id,d.reference,d.provider,d.provider_transaction_id,d.amount,d.currency,d.verified_amount,d.verified_currency,d.status,d.created_at,d.updated_at)`},
	{"withdrawal references, balances, actor attribution, and states preserved", `SELECT w.id FROM {{source}}.wallet_withdrawals w JOIN {{target}}.legacy_import_mappings m ON m.source_table='wallets' AND m.source_id=w.wallet_id JOIN {{target}}.legacy_import_mappings u ON u.source_table='users' AND u.source_id=w.user_id LEFT JOIN {{target}}.legacy_import_mappings a ON a.source_table='users' AND a.source_id=w.approved_by
 LEFT JOIN {{target}}.wallet_withdrawals n ON n.id=w.id WHERE n.id IS NULL OR ROW(n.wallet_id,n.farmer_id,n.reference,n.amount,n.currency,n.status,n.approved_by,n.provider_transfer_id,n.created_at,n.updated_at) IS DISTINCT FROM ROW(m.target_id,u.target_id,w.reference,w.amount,w.currency,w.status,a.target_id,w.provider_transfer_id,w.created_at,w.updated_at)`},
	{"transfer references, balances, ownership, approvers, and states preserved", `SELECT t.id FROM {{source}}.wallet_transfers t JOIN {{target}}.legacy_import_mappings s ON s.source_table='wallets' AND s.source_id=t.sender_wallet_id JOIN {{target}}.legacy_import_mappings r ON r.source_table='wallets' AND r.source_id=t.recipient_wallet_id JOIN {{target}}.legacy_import_mappings su ON su.source_table='users' AND su.source_id=t.sender_id JOIN {{target}}.legacy_import_mappings ru ON ru.source_table='users' AND ru.source_id=t.recipient_id LEFT JOIN {{target}}.legacy_import_mappings a ON a.source_table='users' AND a.source_id=t.approved_by
 LEFT JOIN {{target}}.wallet_transfers n ON n.id=t.id WHERE n.id IS NULL OR ROW(n.sender_wallet_id,n.sender_id,n.recipient_wallet_id,n.recipient_id,n.reference,n.amount,n.currency,n.status,n.approved_by,n.created_at,n.updated_at) IS DISTINCT FROM ROW(s.target_id,su.target_id,r.target_id,ru.target_id,t.reference,t.amount,t.currency,t.status,a.target_id,t.created_at,t.updated_at)`},
	{"orders preserve explicit buyer, item, quantity, totals, and status", `SELECT o.id FROM {{source}}.orders o JOIN {{source}}.order_items i ON i.order_id=o.id JOIN {{target}}.legacy_import_mappings m ON m.source_table='orders' AND m.source_id=o.id JOIN {{target}}.legacy_import_mappings u ON u.source_table='users' AND u.source_id=o.buyer_id JOIN {{target}}.legacy_import_mappings p ON p.source_table='products' AND p.source_id=i.product_id
 LEFT JOIN {{target}}.orders n ON n.id=m.target_id WHERE n.id IS NULL OR n.buyer_id<>u.target_id OR n.crop_id<>p.target_id OR n.quantity::numeric<>i.quantity OR n.total_price::numeric<>o.total_amount OR ROW(n.status,n.created_at,n.checkout_token) IS DISTINCT FROM ROW(o.status,o.created_at,o.checkout_key)`},
	{"revenue ownership, amounts, references, and rates preserved", `SELECT p.id FROM {{source}}.platform_revenue p JOIN {{target}}.legacy_import_mappings m ON m.source_table='orders' AND m.source_id=p.order_id LEFT JOIN {{target}}.platform_revenue n ON n.id=p.id WHERE n.id IS NULL OR ROW(n.order_id,n.reference,n.gross_amount,n.amount,n.currency,n.rate_percent,n.created_at) IS DISTINCT FROM ROW(m.target_id,p.reference,p.gross_amount,p.amount,p.currency,p.rate_percent,p.created_at)`},
	{"revoked source sessions are never restored", `SELECT 1 FROM {{target}}.sessions`},
	{"old OTP challenges and PINs are not invented", `SELECT 1 FROM {{target}}.otp_codes UNION ALL SELECT 1 FROM {{target}}.wallets WHERE transaction_pin_hash IS NOT NULL`},
}
